<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { onBeforeRouteLeave, useRoute } from 'vue-router'
import { readFeature, writeFeature, featureError, type Attempt, type Feedback, type Page } from '@/services/additionalFeatures'
import { gatewayUrl } from '@/api/authApi'
import { plain } from '@/services/operationsApi'
import '@/components/operations/operations.css'
const route=useRoute(),id=Number(route.params.id),attempt=ref<Attempt>(),answers=ref<Record<number,string>>({}),notes=ref<Feedback[]>([]),error=ref(''),message=ref(''),saving=ref(false),submitting=ref(false),now=ref(Date.now())
let offset=0,dirty=false,stopped=false,autoRetryAt=0,timer:ReturnType<typeof setInterval>|undefined,debounce:ReturnType<typeof setTimeout>|undefined,pending:Promise<void>|undefined
// Autosave waits for a pause in answering; route leave, hiding the tab and submit still save immediately.
const AUTOSAVE_MS=2000
const remaining=computed(()=>Math.max(0,Math.ceil(((attempt.value?.endsAt||now.value)-now.value)/1000)))
const clock=computed(()=>`${Math.floor(remaining.value/60)}:${String(remaining.value%60).padStart(2,'0')}`)
function accept(data:Attempt){attempt.value=data;offset=data.serverNow-Date.now();now.value=Date.now()+offset}
async function load(){try{const data=await readFeature<Attempt>(`/api/nihongo-user/study/attempts/${id}`);if(stopped)return;accept(data);answers.value=Object.fromEntries(data.questions.filter(q=>q.chosen).map(q=>[q.id,q.chosen!]))}catch(cause){error.value=featureError(cause)}}
async function flush(){if(pending){await pending;if(dirty&&!attempt.value?.finished)await flush();return}if(!dirty||!attempt.value||attempt.value.finished||stopped)return;clearTimeout(debounce);const payload={answers:{...answers.value},version:attempt.value.version};dirty=false;saving.value=true;pending=gatewayUrl.put<Attempt>(`/api/nihongo-user/study/attempts/${id}/answers`,payload).then(response=>{if(!stopped){accept(response.data);message.value=response.data.finished?'Đã hết giờ, bài được chấm theo đáp án đã lưu.':'Đã lưu đáp án.'}}).catch(cause=>{dirty=true;error.value=featureError(cause);throw cause}).finally(()=>{pending=undefined;saving.value=false});await pending;if(dirty&&!stopped&&!attempt.value?.finished)await flush()}
function choose(){dirty=true;message.value='Chưa lưu';clearTimeout(debounce);debounce=setTimeout(()=>{void flush().catch(()=>{})},AUTOSAVE_MS)}
async function submit(automatic=false){if(submitting.value||!attempt.value||attempt.value.finished||automatic&&Date.now()<autoRetryAt)return;if(!automatic&&!confirm('Nộp bài? Sau khi nộp bạn không thể sửa đáp án.'))return;submitting.value=true;error.value='';try{await flush();if(attempt.value.finished)return;const data=await writeFeature<Attempt>(`/api/nihongo-user/study/attempts/${id}/submit`,{answers:answers.value,version:attempt.value.version});if(!stopped)accept(data)}catch(cause){error.value=featureError(cause)}finally{submitting.value=false;if(automatic)autoRetryAt=Date.now()+10000}}
async function feedback(){try{notes.value=(await readFeature<Page<Feedback>>(`/api/nihongo-user/study/attempts/${id}/feedback`)).content}catch(cause){error.value=featureError(cause)}}
const hidden=()=>{if(document.hidden&&dirty)void flush().catch(()=>{})}
const leaving=(event:BeforeUnloadEvent)=>{if(dirty||saving.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>{if(dirty||pending){try{await flush()}catch{return confirm('Một số đáp án chưa lưu. Vẫn rời bài làm?')}}return true})
onMounted(async()=>{timer=setInterval(()=>{now.value=Date.now()+offset;if(attempt.value&&!attempt.value.finished&&remaining.value===0)void submit(true)},1000);window.addEventListener('beforeunload',leaving);document.addEventListener('visibilitychange',hidden);await load();if(!stopped)await feedback()})
onUnmounted(()=>{stopped=true;clearInterval(timer);clearTimeout(debounce);window.removeEventListener('beforeunload',leaving);document.removeEventListener('visibilitychange',hidden)})
</script>
<template><div class="ops-page attempt-page"><RouterLink class="attempt-back" to="/user/assignments"><i class="bi bi-arrow-left" aria-hidden="true"></i>Bài được giao</RouterLink><header class="ops-heading attempt-heading"><div><p class="attempt-eyebrow">Bài làm trực tuyến</p><h1>{{ attempt?.title || 'Đang tải bài làm...' }}</h1><p v-if="attempt" class="attempt-save-state" role="status"><i class="bi" :class="saving ? 'bi-cloud-arrow-up' : 'bi-cloud-check'" aria-hidden="true"></i>{{ saving ? 'Đang lưu đáp án' : message || 'Đáp án được lưu tự động' }}</p></div><strong v-if="attempt && !attempt.finished" class="attempt-timer" role="timer"><i class="bi bi-stopwatch" aria-hidden="true"></i><span>Còn<strong>{{ clock }}</strong></span></strong></header><p v-if="error" class="ops-error" role="alert">{{ error }} <button class="ops-button secondary" @click="flush().catch(()=>{})">Thử lưu lại</button></p><div v-if="!attempt && !error" class="attempt-loading" role="status"><span></span>Đang tải nội dung bài...</div><section v-if="attempt?.finished" class="ops-panel result-panel"><span class="result-icon"><i class="bi bi-award" aria-hidden="true"></i></span><div><p>Kết quả bài làm</p><h2>{{ attempt.score }} / 100 điểm</h2><span>Đúng {{ attempt.correct }} / {{ attempt.total }} câu · {{ attempt.answersVisible ? 'Đáp án đã được mở' : 'Đáp án sẽ mở sau hạn làm đề' }}</span></div></section><section v-for="(question,index) in attempt?.questions || []" :key="question.id" class="ops-panel question-panel"><div class="question-number">Câu {{ index+1 }} <span>/ {{ attempt?.total }}</span></div><h2 class="ops-content">{{ plain(question.content) }}</h2><div class="ops-grid answer-grid"><label v-for="option in ['A','B','C','D'] as const" :key="option" class="answer-option"><input v-model="answers[question.id]" type="radio" :name="`question-${question.id}`" :value="option" :disabled="attempt?.finished || submitting || remaining===0" @change="choose"><span class="option-letter">{{ option }}</span><span>{{ plain(question[`answer${option}`]) }}</span></label></div><p v-if="question.correctAnswer" class="answer-result"><i class="bi bi-check-circle" aria-hidden="true"></i>Đáp án: {{ question.correctAnswer }} · Bạn chọn: {{ question.chosen || 'Chưa chọn' }}</p></section><div v-if="attempt && !attempt.finished" class="ops-actions submit-bar"><span><i class="bi bi-shield-check" aria-hidden="true"></i>Kiểm tra đáp án trước khi nộp</span><div><button class="ops-button secondary" :disabled="saving||submitting" @click="flush().catch(()=>{})">Lưu đáp án</button><button class="ops-button" :disabled="submitting" @click="submit()">{{ submitting?'Đang nộp...':'Nộp bài' }}</button></div></div><section class="ops-panel feedback-panel"><div><h2>Nhận xét của giảng viên</h2><p class="ops-muted">Phản hồi sẽ xuất hiện sau khi giảng viên đánh giá bài làm.</p></div><button class="ops-button secondary" @click="feedback"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i>Cập nhật</button><p v-if="!notes.length" class="feedback-empty">Chưa có nhận xét.</p><article v-for="note in notes" :key="note.id"><strong>{{ note.questionId ? `Câu có mã ${note.questionId}` : 'Nhận xét chung' }}</strong><p class="ops-content">{{ note.text }}</p></article></section></div></template>

<style scoped>
.attempt-page { max-width: 980px; padding-top: 24px; color: #574b60; }.attempt-back { display: inline-flex; align-items: center; gap: 7px; margin-bottom: 14px; color: #80628e; font-size: 12px; font-weight: 650; }.attempt-heading { align-items: center; padding: 24px 28px; border: 1px solid #e4d9e3; border-radius: 20px; background: linear-gradient(125deg,#fff9f5ed,#f4edf9ed); box-shadow: 0 10px 28px #73627b12; }.attempt-heading h1 { color: #50435e; }.attempt-eyebrow { margin: 0 0 6px !important; color: #9a7da5 !important; font-size: var(--learn-text-xs); font-weight: 750; letter-spacing: .13em; text-transform: uppercase; }.attempt-save-state { display: flex; align-items: center; gap: 6px; margin: 8px 0 0 !important; color: #8d8095 !important; font-size: var(--learn-text-xs); }.attempt-timer { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border: 1px solid #e2d5e6; border-radius: 12px; background: #ffffffb3; color: #886994; }.attempt-timer > span { display: grid; color: #9b8ba1; font-size: var(--learn-text-xs); font-weight: 500; }.attempt-timer strong { color: #624c6c; font-size: 18px; }
.attempt-loading { display: grid; justify-items: center; gap: 12px; padding: 50px; color: #8e8196; font-size: 12px; }.attempt-loading span { width: 28px; height: 28px; border: 3px solid #e8dfea; border-top-color: #896a96; border-radius: 50%; animation: spin .7s linear infinite; }.ops-panel { border-color: #e6dfe8; border-radius: 18px; box-shadow: 0 6px 20px #55475e0a; }.question-panel { padding: 24px; }.question-number { margin-bottom: 12px; color: #8b6d98; font-size: var(--learn-text-xs); font-weight: 750; text-transform: uppercase; letter-spacing: .08em; }.question-number span { color: #b0a3b5; }.question-panel > h2 { color: #55485e; font-size: 17px; line-height: 1.65; }.answer-grid { grid-template-columns: repeat(2,minmax(0,1fr)); margin-top: 18px; }.answer-option { display: flex; align-items: center; gap: 10px; min-width: 0; min-height: 54px; padding: 11px 13px; border: 1px solid #e6dfe8; border-radius: 12px; background: #fcfbfd; color: #6b5f72; font-size: 13px; cursor: pointer; }.answer-option:hover { border-color: #cdbbd5; background: #f8f2fa; }.answer-option:has(input:checked) { border-color: #a98bb6; background: #f2e8f5; box-shadow: 0 0 0 2px #a98bb61f; }.answer-option input { position: absolute; opacity: 0; }.option-letter { display: grid; place-items: center; width: 30px; height: 30px; flex-shrink: 0; border-radius: 9px; background: #eee7f1; color: #7b6087; font-weight: 750; }.answer-option:has(input:checked) .option-letter { background: #80628e; color: #fff; }.answer-result { display: flex; align-items: center; gap: 7px; margin: 14px 0 0; padding: 11px 13px; border-radius: 10px; background: #edf7f1; color: #568267; font-size: 12px; }
.ops-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 42px; border-color: #80628e; border-radius: 10px; background: #80628e; font-size: 12px; }.ops-button.secondary { border-color: #d9cbe1; color: #705582; }.ops-error { border: 1px solid #f1d7d4; border-radius: 12px; }.result-panel { display: flex; align-items: center; gap: 16px; border-color: #dceadf; background: #f8fcf9; }.result-icon { display: grid; place-items: center; width: 48px; height: 48px; flex-shrink: 0; border-radius: 15px; background: #e5f3ea; color: #568267; font-size: 22px; }.result-panel p,.result-panel h2 { margin: 0; }.result-panel p,.result-panel span { color: #7c8e82; font-size: var(--learn-text-xs); }.result-panel h2 { margin: 3px 0; color: #4e6f59; }
.submit-bar { position: sticky; bottom: 12px; z-index: 5; justify-content: space-between; padding: 14px 16px; border: 1px solid #e0d5e4; border-radius: 14px; background: #fffdfdeb; box-shadow: 0 12px 34px #4938531c; backdrop-filter: blur(10px); }.submit-bar > span { display: flex; align-items: center; gap: 7px; color: #8d8095; font-size: var(--learn-text-xs); }.submit-bar > div { display: flex; gap: 8px; }.feedback-panel { margin-top: 22px; }.feedback-panel > div:first-child { display: flex; justify-content: space-between; gap: 12px; }.feedback-empty { padding: 16px; margin: 14px 0 0; border-radius: 11px; background: #f8f5f9; color: #95879d; font-size: 12px; text-align: center; }.feedback-panel article { padding: 14px 0; border-top: 1px solid #eee8f0; }
@keyframes spin { to { transform: rotate(360deg); } }
@media(max-width:650px) { .attempt-page { padding-inline: 0; }.attempt-heading { align-items: stretch; flex-direction: column; padding: 20px 18px; }.attempt-timer { width: fit-content; }.answer-grid { grid-template-columns: minmax(0,1fr); }.question-panel { padding: 18px; }.submit-bar { align-items: stretch; flex-direction: column; bottom: 8px; }.submit-bar > div { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); }.feedback-panel > div:first-child { display: block; } }
@media(prefers-reduced-motion:reduce) { .attempt-loading span { animation: none; } }
</style>
